def calculate_reliability(statement: str, comp_reliabilities: dict[str, float]) -&gt; float:
    system = EXPR[statement]
    num_rows = len(system)
    reliability = 0.0

    for row in range(num_rows):
        if system[row] == "1":
            row_probability = 1.0

            for var in USED_VARS:
                comp_reliability = comp_reliabilities[var]

